const menu=document.querySelector('.menu-toggle');
const nav=document.querySelector('#navigation');
function closeMenu(){menu.setAttribute('aria-expanded','false');nav.classList.remove('is-open');}
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('is-open',open);});
nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menu.getAttribute('aria-expanded')==='true'){closeMenu();menu.focus();}});
document.addEventListener('click',e=>{if(!e.target.closest('.header'))closeMenu();});
matchMedia('(min-width:701px)').addEventListener('change',closeMenu);
const form=document.querySelector('#contact-form');const vehicle=document.querySelector('#vehicle');const interest=document.querySelector('#interest');const message=document.querySelector('#message');function summary(){return 'Assunto: '+interest.value+(vehicle.value.trim()?'\nVeículo: '+vehicle.value.trim():'')+(message.value.trim()?'\nDetalhes: '+message.value.trim():'');}function update(){document.querySelector('#message-preview').textContent=summary();}form.addEventListener('input',update);form.addEventListener('change',update);form.addEventListener('submit',e=>{e.preventDefault();window.open('https://wa.me/5511944564102?text='+encodeURIComponent('Olá, Dantas Prime Films! Gostaria de conversar sobre películas automotivas.\n\n'+summary()),'_blank','noopener');});update();document.querySelectorAll('.stages details').forEach(d=>d.addEventListener('toggle',()=>{if(d.open)document.querySelectorAll('.stages details').forEach(o=>{if(o!==d)o.open=false;});}));
if('IntersectionObserver'in window&&!matchMedia('(prefers-reduced-motion:reduce)').matches){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.remove('pending');observer.unobserve(entry.target);}}),{threshold:.08});document.querySelectorAll('[data-reveal]').forEach((element,index)=>{element.style.setProperty('--delay',`${index%3*65}ms`);element.classList.add('pending');observer.observe(element);});}
document.addEventListener('visibilitychange',()=>document.body.classList.toggle('paused',document.hidden));
const floating=document.querySelector('.whatsapp');const protectedElements=[...document.querySelectorAll('h1,h2,h3,p,figcaption,.button,label,input,select,textarea,summary,.text-link,.phone,.email,.service-list button,.footer-top a,.footer-bottom a')];let floatingFrame=false;
function placeFloating(){floatingFrame=false;floating.classList.remove('is-hidden','on-left');const overlap=()=>{const b=floating.getBoundingClientRect();return protectedElements.some(e=>{const r=e.getBoundingClientRect();return r.width>0&&r.left<b.right+8&&r.right>b.left-8&&r.top<b.bottom+8&&r.bottom>b.top-8;});};if(overlap()){floating.classList.add('on-left');if(overlap())floating.classList.add('is-hidden');}}
function queueFloating(){if(!floatingFrame){floatingFrame=true;requestAnimationFrame(placeFloating);}}
window.addEventListener('scroll',queueFloating,{passive:true});window.addEventListener('resize',queueFloating);document.fonts.ready.then(placeFloating);
